'use client';

import { Fragment, type ElementType } from 'react';
import './staggered-text.css';

export interface StaggeredTextProps {
  text: string;
  /** Element to render, for example "h2". */
  as?: ElementType;
  /** Delay between words, in milliseconds. */
  stagger?: number;
  className?: string;
}

/** Word-by-word entrance. Screen readers get the sentence in one piece. */
export function StaggeredText({
  text,
  as: Tag = 'p',
  stagger = 70,
  className = '',
}: StaggeredTextProps) {
  const words = text.split(/\s+/).filter(Boolean);
  return (
    <Tag className={`mg-stagger ${className}`}>
      <span className='mg-stagger__sr'>{text}</span>
      <span aria-hidden='true'>
        {words.map((word, index) => (
          <Fragment key={index}>
            <span
              className='mg-stagger__word'
              style={{ animationDelay: `${index * stagger}ms` }}
            >
              {word}
            </span>{' '}
          </Fragment>
        ))}
      </span>
    </Tag>
  );
}

.mg-stagger {
  margin: 0;
  font: inherit;
}

.mg-stagger__word {
  display: inline-block;
  animation: mg-stagger-in 520ms cubic-bezier(0.2, 0.7, 0.2, 1) both;
}

.mg-stagger__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@keyframes mg-stagger-in {
  from {
    opacity: 0;
    transform: translateY(0.6em);
    filter: blur(4px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-stagger__word {
    animation: none;
  }
}
